/** Fresh initial grant: permission, floor and head belong to the same statement. */
public Page subscription(Auth.Identity who,long room,long cursor) {
    if(room<1||cursor<0)throw Fault.invalid();
    Page page=batchHistory(who,room,cursor,0);
    // batchHistory clamps its page base for shared reads; a new grant must
    // validate the ORIGINAL client cursor, never silently bootstrap it.
    if(cursor<page.floor()-1)throw new Fault("RESYNC_REQUIRED",409);
    if(cursor>page.head())throw new Fault("INVALID_CURSOR",409);
    who.check();return new Page(room,page.floor(),page.head(),page.head(),cursor,List.of());
}
/** Fresh statement authorizes first; shared additional identities need a prior grant. */
Page batchHistory(Auth.Identity first,long room,long after,long end) {
    return permit(reads,()->{
        first.check();
        // One InnoDB consistent SELECT owns permission, F, H and bodies together.
        // No cached head or separate READ COMMITTED metadata SELECT is involved.
        String meta="SELECT r.head,r.floor_seq";
        String authorized=" FROM room r JOIN membership a ON a.room_id=r.id AND a.user_id=?";
        String query=end==0?meta+authorized+" WHERE r.id=?":
            meta+",m.*"+authorized+" LEFT JOIN message m ON m.room_id=r.id AND m.seq>GREATEST(?,r.floor_seq-1) AND m.seq<=LEAST(?,r.head) WHERE r.id=? ORDER BY m.seq LIMIT 64";
        Object[] args=end==0?new Object[]{first.user(),room}:new Object[]{first.user(),after,end,room};
        Page page=jdbc.query(query,rs->{
            if(!rs.next())throw new Fault("FORBIDDEN",403);
            long head=rs.getLong("head"),floor=rs.getLong("floor_seq");
            var messages=new java.util.ArrayList<Message>();
            if(end!=0)do{if(rs.getObject("seq")!=null)messages.add(MESSAGE.mapRow(rs,0));}while(rs.next());
            return new Page(room,floor,head,Math.min(head,end),Math.max(after,floor-1),List.copyOf(messages));
        },args);
        // Hook now pauses after the complete statement snapshot, before callbacks.
        hooks.hit("batch.after_statement");
        hooks.hit("history.after_head");first.check();
        long base=page.base();var messages=page.messages();
        long expected=base+1;for(Message m:messages)if(m.seq()!=expected++)throw new Fault("LOG_GAP",503);
        metrics.inc("history_queries");metrics.add("history_rows",messages.size());return page;

private void subscribe(Peer p,JsonNode node){
    String id=node.path("sub").asText(),generation=node.path("generation").asText();long room=node.path("room").asLong(-1),cursor=node.path("cursor").asLong(-1);
    if(!id.matches("[A-Za-z0-9_-]{1,64}")||!generation.matches("[A-Za-z0-9_-]{1,64}")||room<1||cursor<0)throw Fault.invalid();
    if(p.subs.size()>=4||p.subs.containsKey(id)||p.subs.values().stream().anyMatch(s->s.room==room))throw new Fault("SUBSCRIPTION_LIMIT",429);
    Sub s=new Sub(p,id,room,cursor,generation);p.subs.put(id,s);s.loading=true;
    long queuedAt=System.nanoTime();String stage="subscribe_"+Metrics.roomClass(room);
    submit(p,()->{
        metrics.time(stage+"_wait",System.nanoTime()-queuedAt);
        try {Store.Page page;long queryAt=System.nanoTime();
            try{page=store.subscription(p.who,room,cursor);}finally{metrics.time(stage+"_query",System.nanoTime()-queryAt);}
            long callbackAt=System.nanoTime();
            synchronized(p){if(p.closing||p.subs.get(id)!=s)return;p.who.check();s.ready=true;s.loading=false;s.h=page.head();s.o=Math.max(s.o,s.h);s.nextHead=System.currentTimeMillis()+headInterval;
                routes.compute(room,(k,set)->{if(set==null)set=ConcurrentHashMap.newKeySet();set.add(s);return set;});
                control(p,Map.of("type","READY","sub",id,"epoch",s.epoch,"head",s.h,"floor",page.floor(),"generation",generation));}
            metrics.time(stage+"_callback",System.nanoTime()-callbackAt);
        }catch(Exception e){metrics.inc(stage+"_failed");synchronized(p){if(p.subs.get(id)==s){p.subs.remove(id);error(p,id,code(e));}}}
    },()->{metrics.inc(stage+"_io_rejected");s.loading=false;p.subs.remove(id);error(p,id,"BUSY");});

