async function receive(m,socket,generation){if(socket!==ws||generation!==connection)return;
  if(m.type==='LIST'){for(const item of m.rooms){const old=summaries.get(item.room);if(!old||item.head>=old.head){summaries.set(item.room,{...item,read:Math.max(old?.read||0,item.read)});}}renderRooms();return;}
  if(m.type==='READY'&&current?.id===m.sub){current.epoch=m.epoch;reconnectPolicy.ready(performance.now());if(desiredRoom!==current.room){current.retiring=true;emit({type:'UNSUBSCRIBE',sub:current.id,epoch:current.epoch});}status('연결됨 · 저장과 로컬 적용을 구분해 확인합니다.');return;}
  if(m.type==='MESSAGE'){if(current?.id!==m.sub||current.epoch!==m.epoch)throw new Error('오래된 구독 본문');const state=await apply(m.message);if(socket===ws)emit({type:'APPLIED',sub:m.sub,epoch:m.epoch,cursor:state.cursor});await render();return;}
  if(m.type==='HEAD'&&current?.id===m.sub&&current.epoch===m.epoch){const state=await localRoom(current.room);emit({type:'APPLIED',sub:m.sub,epoch:m.epoch,cursor:state.cursor});return;}
  if(m.type==='SUBSCRIPTION_CLOSED'&&current?.id===m.sub){const state=await localRoom(current.room);emit({type:'CLOSE_ACK',sub:m.sub,epoch:m.epoch,cursor:state.cursor,discarded:m.issued-state.cursor});return;}
  if(m.type==='CLOSE_CONFIRMED'&&current?.id===m.sub){current=null;if(desiredRoom)await subscribe(desiredRoom);return;}
  if(m.type==='ERROR'){status('서버 응답: '+m.error);if(m.error==='BUSY'&&current?.id===m.sub&&!current.epoch){const retrySub=current;setTimeout(async()=>{if(socket===ws&&current===retrySub&&!current.epoch){const state=await localRoom(current.room);emit({type:'SUBSCRIBE',sub:current.id,room:current.room,cursor:state.cursor,generation:state.generation});}},100+Math.random()*200);}if(m.error==='RESYNC_REQUIRED'){desiredRoom=null;status('보관 범위를 벗어났습니다. 최근 32개로 다시 시작을 선택하세요.');}return;}
}
