// Same automatic-reconnect state machine in the browser and k6.
// One bounded fast retry after a stable READY; OPEN alone never resets failures.
globalThis.StoryBridgeRetry=function(index,random){
 let failures=0,readyAt=null;
 if(!random){
  if(typeof index==='number'){
   // Reproducible per-recipient diagnostic RNG, not a tuned schedule or room priority.
   let seed=Math.imul(index+1,2654435761)>>>0;
   random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  }else random=Math.random;
 }
 return {
  connecting(){readyAt=null;},
  ready(at){readyAt=at;},
  next(at){
   const stable=readyAt!==null&&at-readyAt>=10000;readyAt=null;
   if(stable)failures=0;
   if(failures===0&&stable){failures=1;return 25+300*random();}
   const level=Math.max(1,failures);failures=Math.min(31,level+1);
   const cap=Math.min(5000,1000*2**Math.min(level-1,3));
   return cap/2+cap/2*random();
  }
 };
